5 130 / 12%);\n  --warning: var(--ci-warning);\n  --success: var(--ci-success);\n  --ci-mobile-safe-top: max(env(safe-area-inset-top, 0px), 28px);\n  --ci-mobile-safe-bottom: max(env(safe-area-inset-bottom, 0px), 18px);\n  --ci-mobile-safe-left: env(safe-area-inset-left, 0px);\n  --ci-mobile-safe-right: env(safe-area-inset-right, 0px);\n\n  position: relative;\n  display: grid;\n  width: 100%;\n  height: 100%;\n  padding: 24px;\n  overflow: auto;\n  place-items: center;\n  color: var(--text);\n  font-family:\n    Inter,\n    'Noto Sans SC',\n    'Microsoft YaHei',\n    system-ui,\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    sans-serif;\n}\n\n.backdrop {\n  position: fixed;\n  z-index: 0;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  padding: 0;\n  background: var(--ci-overlay);\n  border: 0;\n  backdrop-filter: blur(9px);\n  cursor: default;\n}\n\n.editor-notice {\n  position: fixed;\n  z-index: 20;\n  top: max(calc(env(safe-area-inset-top, 0px) + 14px), 18px);\n  left: 50%;\n  width: min(560px, calc(100% - 32px));\n  padding: 11px 14px;\n  color: var(--text);\n  background: color-mix(in srgb, var(--warning) 18%, var(--surface-raised));\n  border: 1px solid color-mix(in srgb, var(--warning) 58%, var(--border));\n  border-radius: 12px;\n  box-shadow: 0 14px 34px rgb(0 0 0 / 28%);\n  font-size: 12px;\n  font-weight: 750;\n  line-height: 1.5;\n  text-align: center;\n  transform: translateX(-50%);\n  pointer-events: none;\n}\n\n.manager-dialog {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  width: min(1420px, 100%);\n  height: min(720px, calc(100% - 8px));\n  max-height: calc(100% - 8px);\n  overflow: hidden;\n  flex-direction: column;\n  background: radial-gradient(circle at 0 0, rgb(var(--ci-primary-rgb) / 8%), transparent 28rem), var(--bg);\n  border: 1px solid var(--border-strong);\n  border-radius: 20px;\n  box-shadow: 0 28px 90px rgb(0 0 0 / 55%);\n}\n\n.dialog-header {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  padding: 22px 26px;\n  background: var(--ci-header);\n  border-bottom: 1px solid var(--border);\n}\n\n.dialog-header h1 {\n  margin: 0;\n}\n\n.header-title {\n  display: flex;\n  min-width: 0;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 10px;\n}\n\n.header-title-copy {\n  display: flex;\n  min-width: 0;\n  align-items: center;\n  gap: 10px;\n}\n\n.dialog-header h1 {\n  overflow: hidden;\n  font-size: clamp(22px, 3vw, 31px);\n  line-height: 1.2;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.header-actions {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 10px;\n}\n\n.header-back-button {\n  display: grid;\n  width: 40px;\n  height: 40px;\n  padding: 0;\n  flex: 0 0 auto;\n  place-items: center;\n  color: var(--text-secondary);\n  background: transparent;\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  font-size: 20px;\n  cursor: pointer;\n}\n\n.header-back-button:hover {\n  color: var(--text);\n  background: var(--surface-soft);\n}\n\n.viewer-preview-trigger,\n.return-library-button {\n  min-height: 40px;\n}\n\n.return-library-button {\n  white-space: nowrap;\n}\n\n.profile-editor-viewer-preview {\n  position: fixed;\n  z-index: 20;\n  top: 50%;\n  left: 50%;\n  display: flex;\n  width: min(1400px, calc(100vw - 24px));\n  height: calc(100dvh - 24px);\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n  flex-direction: column;\n  transform: translate(-50%, -50%);\n  background: var(--bg);\n  border: 1px solid var(--border-strong);\n  border-radius: 16px;\n  box-shadow: 0 24px 70px rgb(0 0 0 / 48%);\n}\n\n.profile-editor-viewer-preview-header {\n  flex: 0 0 auto;\n  gap: 16px;\n  padding: 12px 14px 12px 18px;\n}\n\n.profile-editor-viewer-preview-toolbar {\n  display: flex;\n  min-width: 0;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 10px;\n}\n\n.profile-editor-viewer-preview-source-state {\n  display: grid;\n  min-width: 92px;\n  gap: 1px;\n  text-align: right;\n}\n\n.profile-editor-viewer-preview-source-state span {\n  color: var(--text-muted);\n  font-size: 10px;\n  font-weight: 700;\n}\n\n.profile-editor-viewer-preview-source-state strong {\n  color: var(--text);\n  font-size: 12px;\n}\n\n.profile-editor-viewer-preview-source-toggle {\n  min-height: 34px;\n  padding: 7px 10px;\n}\n\n.profile-editor-viewer-preview-source {\n  display: grid;\n  flex: 0 0 auto;\n  gap: 8px;\n  padding: 10px 14px;\n  background: var(--surface-soft);\n  border-bottom: 1px solid var(--border);\n}\n\n.profile-editor-viewer-preview-input {\n  display: grid;\n  gap: 6px;\n}\n\n.profile-editor-viewer-preview-input textarea {\n  min-height: 110px;\n  max-height: 220px;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\n\n.profile-editor-viewer-preview-stage {\n  display: flex;\n  flex: 1 1 auto;\n  min-width: 0;\n  min-height: 0;\n  padding: 12px;\n  overflow: hidden;\n  align-items: center;\n  justify-content: center;\n}\n\n.profile-editor-viewer-preview-frame {\n  position: relative;\n  flex: 0 0 auto;\n  min-width: 1px;\n  min-height: 1px;\n}\n\n.profile-editor-viewer-preview-canvas {\n  width: 1200px;\n  max-width: none;\n  transform-origin: top left;\n  will-change: transform;\n}\n\n.profile-editor-viewer-preview-empty {\n  display: grid;\n  min-height: 800px;\n  place-items: center;\n  padding: 32px;\n  color: var(--text-muted);\n  text-align: center;\n}\n\n.phase-badge {\n  padding: 5px 8px;\n  color: var(--primary);\n  background: var(--primary-soft);\n  border: 1px solid rgb(var(--ci-primary-rgb) / 25%);\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 800;\n}\n.close-button,\n.icon-button {\n  display: grid;\n  width: 40px;\n  height: 40px;\n  padding: 0;\n  place-items: center;\n  background: var(--surface-soft);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  cursor: pointer;\n}\n\n.close-button {\n  font-size: 25px;\n  line-height: 1;\n}\n\n.dialog-body {\n  display: grid;\n  min-height: 0;\n  overflow: hidden;\n  flex: 1 1 auto;\n  grid-template-columns: 272px minmax(0, 1fr);\n}\n\n.dialog-body.mode-selection-body,\n.dialog-body.flash-mode {\n  display: flex;\n  overflow: hidden;\n}\n\n.mode-selection {\n  display: grid;\n  width: min(960px, 100%);\n  min-height: 0;\n  margin: auto;\n  padding: clamp(28px, 5vw, 58px);\n  overflow-y: auto;\n  gap: 28px;\n}\n\n.mode-selection-hero {\n  display: grid;\n  max-width: 720px;\n  gap: 8px;\n}\n\n.mode-eyebrow {\n  color: var(--primary);\n  font-size: 11px;\n  font-weight: 800;\n  letter-spacing: 0.08em;\n}\n\n.mode-selection-hero h2,\n.flash-mode-heading h2 {\n  margin: 0;\n  color: var(--text);\n  font-size: clamp(24px, 4vw, 36px);\n  line-height: 1.18;\n}\n\n.mode-selection-hero > strong {\n  overflow: hidden;\n  color: var(--text-secondary);\n  font-size: 16px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.mode-selection-hero p,\n.flash-mode-heading p {\n  max-width: 700px;\n  margin: 0;\n  color: var(--text-muted);\n  font-size: 13px;\n  line-height: 1.7;\n}\n\n.mode-choice-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 18px;\n}\n\n.mode-choice-card {\n  --mode-accent: var(--primary);\n  --mode-accent-rgb: var(--ci-primary-rgb);\n\n  position: relative;\n  display: grid;\n  min-width: 0;\n  min-height: 206px;\n  padding: 0;\n  overflow: visible;\n  grid-template-areas:\n    'stub copy'\n    'stub action';\n  grid-template-columns: 88px minmax(0, 1fr);\n  grid-template-rows: 1fr auto;\n  color: var(--text);\n  text-align: left;\n  background:\n    radial-gradient(circle at 100% 0, rgb(var(--mode-accent-rgb) / 13%), transparent 48%),\n    linear-gradient(145deg, rgb(var(--mode-accent-rgb) / 7%), var(--surface) 62%);\n  border: 1px solid rgb(var(--mode-accent-rgb) / 32%);\n  border-radius: 20px;\n  box-shadow:\n    0 12px 28px rgb(0 0 0 / 16%),\n    inset 0 1px 0 rgb(255 255 255 / 4%);\n  cursor: pointer;\n  transition:\n    transform 160ms ease,\n    border-color 160ms ease,\n    box-shadow 160ms ease;\n}\n\n.mode-choice-card.flash {\n  --mode-accent: #e1ad5d;\n  --mode-accent-rgb: 225 173 93;\n}\n\n.mode-choice-card.pro {\n  --mode-accent: #8fa9ed;\n  --mode-accent-rgb: 143 169 237;\n}\n\n.manager-root.char-info-theme-light .mode-choice-card.flash {\n  --mode-accent: #9b641d;\n  --mode-accent-rgb: 190 127 45;\n}\n\n.manager-root.char-info-theme-light .mode-choice-card.pro {\n  --mode-accent: #526fbd;\n  --mode-accent-rgb: 82 111 189;\n}\n\n.mode-choice-card:hover:not(:disabled),\n.mode-choice-card:focus-visible:not(:disabled) {\n  border-color: rgb(var(--mode-accent-rgb) / 64%);\n  box-shadow:\n    0 16px 38px rgb(0 0 0 / 23%),\n    0 0 0 1px rgb(var(--mode-accent-rgb) / 10%);\n  transform: translateY(-2px);\n  outline: none;\n}\n\n.mode-choice-card:focus-visible:not(:disabled) {\n  outline: 2px solid rgb(var(--mode-accent-rgb) / 74%);\n  outline-offset: 3px;\n}\n\n.mode-choice-card:disabled {\n  opacity: 0.55;\n  cursor: wait;\n}\n\n.mode-choice-stub {\n  position: relative;\n  display: grid;\n  min-height: 100%;\n  padding: 18px 10px;\n  grid-area: stub;\n  place-items: center;\n  align-content: center;\n  gap: 12px;\n  color: var(--mode-accent);\n  background: linear-gradient(180deg, rgb(var(--mode-accent-rgb) / 20%), rgb(var(--mode-accent-rgb) / 8%));\n  border-right: 1px dashed rgb(var(--mode-accent-rgb) / 36%);\n  border-radius: 19px 0 0 19px;\n}\n\n.mode-choice-stub::before,\n.mode-choice-stub::after {\n  position: absolute;\n  right: -9px;\n  width: 16px;\n  height: 16px;\n  content: '';\n  background: var(--bg);\n  border: 1px solid rgb(var(--mode-accent-rgb) / 28%);\n  border-radius: 50%;\n}\n\n.mode-choice-stub::before {\n  top: -9px;\n}\n\n.mode-choice-stub::after {\n  bottom: -9px;\n}\n\n.mode-choice-ticket-label {\n  font-size: 9px;\n  font-weight: 900;\n  letter-spacing: 0.16em;\n  writing-mode: vertical-rl;\n  transform: rotate(180deg);\n  opacity: 0.72;\n}\n\n.mode-choice-icon {\n  display: grid;\n  width: 46px;\n  height: 46px;\n  place-items: center;\n  color: var(--mode-accent);\n  background: rgb(var(--mode-accent-rgb) / 12%);\n  border: 1px solid rgb(var(--mode-accent-rgb) / 34%);\n  border-radius: 14px;\n  box-shadow: inset 0 1px 0 rgb(255 255 255 / 5%);\n  font-size: 22px;\n}\n\n.mode-choice-copy {\n  display: grid;\n  min-width: 0;\n  padding: 23px 24px 8px;\n  grid-area: copy;\n  align-content: start;\n  gap: 8px;\n}\n\n.mode-choice-copy > strong {\n  color: var(--text);\n  font-size: 23px;\n  line-height: 1.2;\n}\n\n.mode-choice-copy > small {\n  min-height: 3.2em;\n  color: var(--text-secondary);\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.mode-choice-fields {\n  color: var(--text-muted);\n  font-size: 11px;\n  line-height: 1.5;\n}\n\n.mode-choice-action {\n  display: flex;\n  padding: 10px 24px 22px;\n  grid-area: action;\n  align-items: center;\n  justify-content: space-between;\n  color: var(--mode-accent);\n  font-size: 13px;\n  font-weight: 850;\n}\n\n.mode-choice-action > span {\n  font-size: 18px;\n  line-height: 1;\n  transition: transform 160ms ease;\n}\n\n.mode-choice-card:hover:not(:disabled) .mode-choice-action > span,\n.mode-choice-card:focus-visible:not(:disabled) .mode-choice-action > span {\n  transform: translateX(3px);\n}\n\n.flash-mode-editor {\n  display: flex;\n  min-width: 0;\n  min-height: 0;\n  flex: 1 1 auto;\n  flex-direction: column;\n}\n\n.flash-mode-gallery {\n  display: grid;\n  width: min(760px, 100%);\n  min-height: 0;\n  margin: auto;\n  padding: clamp(28px, 5vw, 54px);\n  overflow-y: auto;\n  align-content: center;\n  gap: 24px;\n}\n\n.flash-mode-heading {\n  display: grid;\n  gap: 8px;\n}\n\n.flash-mode-form,\n.flash-tutorial-step {\n  display: grid;\n  gap: 16px;\n}\n\n.flash-onboarding {\n  align-content: start;\n}\n\n.flash-progress {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.flash-progress span {\n  padding: 8px 10px;\n  color: var(--text-muted);\n  text-align: center;\n  background: var(--surface-soft);\n  border: 1px solid var(--border);\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 800;\n}\n\n.flash-progress span.active {\n  color: var(--ci-on-primary);\n  background: var(--primary);\n  border-color: var(--primary);\n}\n\n.flash-progress span.complete {\n  color: var(--success);\n  border-color: color-mix(in srgb, var(--success) 40%, var(--border));\n}\n\n.flash-source-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.flash-source-grid button,\n.flash-character-results button {\n  display: grid;\n  min-width: 0;\n  padding: 13px 14px;\n  gap: 4px;\n  color: var(--text-secondary);\n  text-align: left;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  cursor: pointer;\n}\n\n.flash-source-grid button:hover,\n.flash-source-grid button.active,\n.flash-character-results button:hover {\n  color: var(--text);\n  background: var(--primary-soft);\n  border-color: var(--primary-strong);\n}\n\n.flash-source-grid button strong,\n.flash-character-results button strong {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.flash-source-grid button small,\n.flash-character-results button small {\n  color: var(--text-muted);\n  font-size: 10px;\n  line-height: 1.4;\n}\n\n.flash-source-panel,\n.pro-current-chat-picker {\n  display: grid;\n  gap: 12px;\n  padding: 14px;\n  background: var(--surface-soft);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n}\n\n.flash-character-results {\n  display: grid;\n  max-height: 260px;\n  overflow-y: auto;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n}\n\n.flash-character-results p {\n  grid-column: 1 / -1;\n  margin: 0;\n  padding: 14px;\n  color: var(--text-muted);\n  text-align: center;\n  font-size: 11px;\n}\n\n.flash-mode-url-field {\n  display: grid;\n  gap: 7px;\n}\n\n.flash-mode-url-fiel